UPDATE ROLES
   SET
       NAME               = COALESCE(#{name}, NAME)
     , REMARK             = COALESCE(#{description}, REMARK)
     , STATUS             = COALESCE(#{status}, STATUS)
     , LAST_CHANGE_BRANCH = #{lastChangeBranch}
     , LAST_CHANGE_USER   = #{lastChangeUser}
     , LAST_CHANGE_DATE   = #{lastChangeDate}
     , LAST_CHANGE_TIME   = #{lastChangeTime}
 WHERE ROLE_ID = #{roleId}


UPDATE ROLES
   SET
       STATUS             = '09'
     , LAST_CHANGE_BRANCH = #{lastChangeBranch}
     , LAST_CHANGE_USER   = #{lastChangeUser}
     , LAST_CHANGE_DATE   = #{lastChangeDate}
     , LAST_CHANGE_TIME   = #{lastChangeTime}
 WHERE ROLE_ID = #{roleId}
